-- MarkanM Chat: 4,000 game questions (Quick Quiz, Would You Rather, Truth or Dare)
-- Automatically creates the game_questions table if it does not exist.

SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE IF NOT EXISTS `game_questions` (
  `id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `game_slug` VARCHAR(50) NOT NULL,
  `category` VARCHAR(50) NOT NULL DEFAULT 'General',
  `question_type` ENUM('quiz', 'wyr', 'truth', 'dare', 'prediction') NOT NULL DEFAULT 'quiz',
  `question_text` TEXT NOT NULL,
  `options_json` JSON DEFAULT NULL,
  `correct_index` TINYINT UNSIGNED DEFAULT 0,
  `difficulty` ENUM('easy', 'medium', 'hard') NOT NULL DEFAULT 'medium',
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_game_slug_type` (`game_slug`, `question_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

